FUNCTION FC_ConcatAll : STRING
VAR_INPUT
	asConcattables					:	ARRAY[0..100] OF STRING;
END_VAR
VAR
	i								:	INT;
	sActual							:	STRING;
	//bStart							:	BOOL := TRUE;
END_VAR

ST.xhtml:
FOR i := 0 TO 100 BY 1 DO
	IF asConcattables[i] <> '' THEN
		sActual := CONCAT(STR1 := sActual , STR2 := asConcattables[i]);
	END_IF
END_FOR

FC_ConcatAll := sActual;

