FUNCTION FUN_Build_String_5 : String(255)
VAR_INPUT
	sString_1			:STRING(255);
	sString_2			:STRING(255);
	sString_3			:STRING(255);
	sString_4			:STRING(255);
	sString_5			:STRING(255);
END_VAR
VAR
END_VAR

ST.xhtml:
IF sString_1 <> ''
	AND sString_2 <>'' 	AND sString_3 <>'' 	AND sString_4 <>'' 	AND sString_5 <>'' THEN

	FUN_Build_String_5:=concat(sString_1,concat(sString_2,concat(sString_3,concat(sString_4,sString_5))));

ELSIF sString_1 <> ''
	AND sString_2 <>'' 	AND sString_3 <>'' 	AND sString_4 <>'' THEN

	FUN_Build_String_5:=concat(sString_1,concat(sString_2,concat(sString_3,sString_4)));
ELSIF sString_1 <> ''
	AND sString_2 <>'' 	AND sString_3 <>'' THEN

	FUN_Build_String_5:=concat(sString_1,concat(sString_2,sString_3));
ELSIF sString_1 <> ''AND sString_2 <>'' THEN

	FUN_Build_String_5:=concat(sString_1,sString_2);
ELSE
	FUN_Build_String_5:='';
END_IF

