FUNCTION FUN_Concat_String_100 : STRING [1000]
VAR_INPUT
	arrString:	ARRAY [1..100] OF STRING(1000);
END_VAR
VAR
	i: INT;
	j: INT;
	k: INT;
	iArchive_j		:INT;
	arrTMP255Byte		:ARRAY [1..1000] OF BYTE;
	arrAllStringInByte		:ARRAY [1..1000] OF BYTE;
	sTemp			:STRING(1000);
	iTest1: INT;
	iTest2: UINT;
END_VAR

FUNCTION FUN_Concat_String_100 : STRING [1000]
VAR_INPUT
	arrString:	ARRAY [1..100] OF STRING(1000);
END_VAR
VAR
	i: INT;
	j: INT;
	k: INT;
	iArchive_j		:INT;
	arrTMP255Byte		:ARRAY [1..1000] OF BYTE;
	arrAllStringInByte		:ARRAY [1..1000] OF BYTE;
	sTemp			:STRING(1000);
	iTest1: INT;
	iTest2: UINT;
END_VAR

ST.xhtml:
//	FUN_Concat_String_100:='ERROR FUN_Concat_String_100 to many input character!!!';
MEMSET(ADR(arrAllStringInByte),STRING_TO_BYTE(''),SIZEOF(arrAllStringInByte));
j:=1;
iArchive_j:=1;
FOR i:=1 TO 100 DO
	IF arrString[i] <> ''
		OR arrString[i+1] <> '' THEN
			MEMCPY(ADR(arrTMP255Byte),ADR(arrString[i]),1000);

			k:=1;
			FOR j:=iArchive_j TO (iArchive_j+1000) DO
				IF arrTMP255Byte[k] <> 0 THEN
					arrAllStringInByte[j]:=arrTMP255Byte[k];
					k:=k+1;
				ELSE
					EXIT;
				END_IF
			END_FOR
			iArchive_j:=j;
			IF iArchive_j >=1000 THEN   //ERROR
				FUN_Concat_String_100:='ERROR FUN_Concat_String_100 to many input character!!!';
				EXIT;
			END_IF
	ELSIF i > 1 THEN					//OK
		 MEMCPY(ADR(FUN_Concat_String_100),ADR(arrAllStringInByte),SIZEOF(arrAllStringInByte)); 
		 EXIT;
	ELSIF i = 1 THEN					//ERROR
		FUN_Concat_String_100:='ERROR FUN_Concat_String_100 received no string to the input!!!';
		EXIT;
	ELSE
		EXIT;
	END_IF	
END_FOR

