FUNCTION FUN_CutString : STRING(255)
VAR_INPUT
	sRawString							:STRING[1000];
	sStringStartIdentifier				:STRING;
	sStringEndIdentifier				:STRING;
	sDataElementSeparator				:STRING;
END_VAR
VAR
	iStringFound						:INT;// 1--> string found 0--> no string
	sCutString							:STRING;
	iTemp: INT;
	sTempString: STRING(1000);
	iTempStringEnd: INT;
	iLenghtOfCompleteString: INT;
	iLenghtofStartIdentifier: INT;
END_VAR

FUNCTION FUN_CutString : STRING(255)
VAR_INPUT
	sRawString							:STRING[1000];
	sStringStartIdentifier				:STRING;
	sStringEndIdentifier				:STRING;
	sDataElementSeparator				:STRING;
END_VAR
VAR
	iStringFound						:INT;// 1--> string found 0--> no string
	sCutString							:STRING;
	iTemp: INT;
	sTempString: STRING(1000);
	iTempStringEnd: INT;
	iLenghtOfCompleteString: INT;
	iLenghtofStartIdentifier: INT;
END_VAR

ST.xhtml:
iTemp:=find(sRawString,concat(sDataElementSeparator,sStringStartIdentifier));
iLenghtOfCompleteString:=len(sRawString);
iLenghtofStartIdentifier:=len(concat(sDataElementSeparator,sStringStartIdentifier));

IF iTemp > 0 THEN
	IF iLenghtofStartIdentifier > 1 THEN
		sTempString:=right(sRawString,(iLenghtOfCompleteString-iTemp-(iLenghtofStartIdentifier-1)));
	ELSE
		sTempString:=right(sRawString,(iLenghtOfCompleteString-iTemp));
	END_IF
	iTempStringEnd:=find(sTempString,sStringEndIdentifier);
	IF iTempStringEnd > 0 THEN
		FUN_CutString:=MID(sTempString,iTempStringEnd-1,1);
	ELSE
		FUN_CutString:='';	
	END_IF
ELSE
	FUN_CutString:='';
END_IF

